style.css:
@-moz-document domain("investing.com") {
/* ==========================================================================
       0. CSS VARIABLES & AD BLOCKING
       ========================================================================== */
    :root {
        --bg-primary: #121418;
        --bg-secondary: #1a1d24;
        --bg-tertiary: #232730;
        --bg-hover: #2a2f3a;
        --text-primary: #e2e8f0;
        --text-secondary: #94a3b8;
        --text-muted: #64748b;
        --border-color: #2d3340;
        --accent-blue: #38bdf8;
        --up-green: #22c55e;
        --down-red: #ef4444;
        --up-bg: rgba(34, 197, 94, 0.16);
        --down-bg: rgba(239, 68, 68, 0.16);
    }

    .adBlock, [id*="div-gpt-ad"], [class*="AdSlot"], [data-test*="ad-slot"], .midHeaderAd, .mid-page-promo-btn-wrapper {
        display: none !important;
    }

    /* ==========================================================================
       1. GLOBAL & BASE CONTAINERS
       ========================================================================== */
    html, body, #__next, .wrapper, .mainContainer, #fullColumn, #leftColumn,
    BODY, [data-test="workstation-tabs"], .qlTooltip, .content, .tooltipPopup, .header {
        background-color: var(--bg-primary) !important;
        color: var(--text-primary) !important;
    }

    /* Generic utility overrides */
    [class*="bg-white"], [class*="bg-[#fff]"], [class*="bg-gray-"], [class*="bg-slate-"],
    .whitebox, .box, .contentBox, .dialog, .popup, .tooltipPopup {
        background-color: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
    }

    header, nav, footer, .topBar, .navBar, .subNav, #navBar, .midHeader {
        background-color: var(--bg-secondary) !important;
        border-color: var(--border-color) !important;
    }

    h1, h2, h3, h4, h5, h6, p, span:not([class*="green"]):not([class*="red"]):not([class*="up"]):not([class*="down"]) {
        color: var(--text-primary);
    }

    a {
        color: var(--text-primary) !important;
        transition: color 0.15s ease;
    }

    a:hover {
        color: var(--accent-blue) !important;
    }

    hr, [class*="border-"], .borderTop, .borderBottom {
        border-color: var(--border-color) !important;
    }

    /* ==========================================================================
       2. PORTFOLIO & WATCHLIST TABLES
       ========================================================================== */
    .portfolioContainer, #portfolioContainer, .watchlistContainer,
    .portfolioHeader, .portfolioSummary, .summaryTable, .portfolioTabs,
    [data-test*="portfolio"], [data-test*="watchlist"], [class*="portfolio_"], [class*="watchlist_"] {
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
    }

    .portfolioTabs li, ul.tabs li, [role="tablist"] button, [role="tab"] {
        background-color: var(--bg-secondary);
        color: var(--text-secondary) !important;
        border-color: var(--border-color) !important;
    }

    .portfolioTabs li.active, ul.tabs li.selected, [role="tab"][aria-selected="true"] {
        background-color: var(--bg-tertiary) !important;
        color: var(--accent-blue) !important;
        border-bottom: 2px solid var(--accent-blue) !important;
    }

    table, .genTbl, .closedTbl, .openTbl, .portfolioTable, .myPortfolioTbl,
    [class*="datatable"], [class*="table_"] {
        background-color: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
    }

    thead, th, .genTbl th, table thead tr {
        background-color: var(--bg-tertiary) !important;
        color: var(--text-secondary) !important;
        border-bottom: 1px solid var(--border-color) !important;
        border-top: 1px solid var(--border-color) !important;
    }

    tbody tr, .genTbl tbody tr, table tr {
        background-color: var(--bg-secondary) !important;
        border-bottom: 1px solid var(--border-color) !important;
    }

    tbody tr:nth-child(even) {
        background-color: #161920 !important;
    }

    tbody tr:hover, .genTbl tbody tr:hover {
        background-color: var(--bg-hover) !important;
    }

    td, .genTbl td {
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
    }

    /* Price Movements & Flashes */
    .greenFont, .pid-up, .up, [class*="text-green"], [class*="positive"],
    td[class*="green"], span[class*="green"], [data-test="instrument-price-change-percent"][class*="positive"] {
        color: var(--up-green) !important;
    }

    .redFont, .pid-down, .down, [class*="text-red"], [class*="negative"],
    td[class*="red"], span[class*="red"], [data-test="instrument-price-change-percent"][class*="negative"] {
        color: var(--down-red) !important;
    }

    .greenBg, [class*="bg-green"], [class*="flash-green"], tr.upBg td {
        background-color: var(--up-bg) !important;
        transition: background-color 0.3s ease !important;
    }

    .redBg, [class*="bg-red"], [class*="flash-red"], tr.downBg td {
        background-color: var(--down-bg) !important;
        transition: background-color 0.3s ease !important;
    }

    /* Inputs, Modals & Dropdowns */
    input, select, textarea, .searchText, .inputBox, [type="text"], [type="number"], [type="search"] {
        background-color: var(--bg-tertiary) !important;
        color: var(--text-primary) !important;
        border: 1px solid var(--border-color) !important;
    }

    input::placeholder, textarea::placeholder {
        color: var(--text-muted) !important;
    }

    .searchPopup, .autoComplete, [class*="autocomplete"], [class*="dropdown"], [role="listbox"] {
        background-color: var(--bg-tertiary) !important;
        border: 1px solid var(--border-color) !important;
        box-shadow: 0 8px 20px rgba(0, 0, 0, 0.6) !important;
    }

    /* Portfolio Tabs & Custom Controls */
    .headBtnWrapper a, .instrumentFloaterInner, .top {
        background-color: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
    }

    .navMenuUL > LI.selected {
        background-color: var(--bg-secondary);
        color: var(--text-primary) !important;
        border: 1px solid var(--accent-blue) !important;
        border-bottom: none !important;
    }

    .selected .editableField {
        background-color: var(--bg-primary) !important;
        color: var(--text-primary) !important;
    }

    .js-portfolio-tab-wrapper.portfolioTab.selected, .portfolioTabs .selected {
        background-color: var(--bg-primary) !important;
        border: 1px solid var(--border-color);
        border-bottom-color: var(--bg-primary) !important;
    }

    .js-portfolio-tab-wrapper-inner.editableField input {
        background-color: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
        border: none !important;
    }

    .js-portfolio-tab-wrapper.portfolioTab.selected input {
        background-color: var(--bg-primary) !important;
    }

    .cardWrapper {
        border-top: 0;
        border: 1px solid var(--border-color);
    }

    .selected {
        background-color: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
    }

    .slideWrapper {
        border-left: 0;
        border-right: 0;
    }

    /* ==========================================================================
       3. FLAGS & SVG ICONS
       ========================================================================== */
    .ceFlags {
        background-image: url(https://i-invdn-com.investing.com/ce_flags_v25.png) !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important;
        width: 16px;
        height: 15px;
        padding: 0;
        display: inline-block;
    }

    .flag, [class*="flag-"], [class*="flag_"], [class*="ceFlags-"], .country-flag {
        background-color: transparent !important;
        display: inline-block !important;
    }

    svg:not([class*="chart"]):not([class*="plot"]) path:not([fill="none"]):not([fill^="#"]):not([fill^="rgb"]) {
        fill: var(--text-secondary) !important;
    }

    i[class*="icon"], span[class*="icon"], [class*="inv-icon"], [class*="invIcon"] {
        background-color: transparent !important;
        color: var(--text-secondary) !important;
    }

    /* ==========================================================================
       4. SECURITY-SPECIFIC PAGES & TAILWIND HELPERS
       ========================================================================== */
    @media (min-width: 1024px) {
        .md\:bg-inv-grey-100 {
            background-color: transparent;
        }
    }

    .text-primary {
        color: var(--text-primary);
    }

    .text-secondary {
        color: var(--text-secondary);
        background: var(--bg-secondary);
    }

    .text-\[\#232526\], .text-white, .text-link, .text-warren-gray-900 {
        color: var(--text-primary) !important;
    }

    .bg-\[\#f8f8f8\], .bg-\[\#F7F7F8\] {
        --tw-bg-opacity: 1;
        background: var(--bg-secondary);
    }

    .bg-\[\#F3F3F3\] {
        background: var(--bg-tertiary);
    }

    .bg-\[\#F3F3F3\]:hover {
        color: var(--accent-blue);
    }

    .bg-\[\#F5F5F5\], .bg-\[\#f2f2f2\], .bg-gray-900 {
        background: var(--bg-tertiary);
    }

    .bg-\[\#F5F5F5\]:hover {
        background: var(--bg-tertiary);
        color: var(--accent-blue) !important;
    }

    .bg-primary {
        background: var(--bg-primary);
    }

    .bg-primary:hover, .bg-secondary:hover {
        background: var(--bg-tertiary);
    }

    .bg-secondary {
        background: var(--bg-secondary);
    }

    .hover\:bg-inv-grey-50:hover, .bg-inv-grey-50 {
        background: var(--bg-secondary);
    }

    /* ==========================================================================
       5. NEWS FEED & ARTICLE PAGES
       ========================================================================== */
    article, .articleItem, .newsItem, .largeTitle .articleItem,
    [data-test="news-list"] > div, [data-test*="article"], [class*="news-item"], [class*="article-item"] {
        background-color: var(--bg-secondary) !important;
        border-color: var(--border-color) !important;
        color: var(--text-primary) !important;
    }

    article:hover, .articleItem:hover {
        background-color: var(--bg-hover) !important;
    }

    .articleItem .title, [data-test="article-title-link"], article h2, article h3 {
        color: var(--text-primary) !important;
        font-weight: 600;
    }

    .articleItem .title:hover, [data-test="article-title-link"]:hover {
        color: var(--accent-blue) !important;
    }

    .articleDetails, .articleItem p, [data-test="article-description"],
    time, .date, .byline, [class*="text-muted"] {
        color: var(--text-secondary) !important;
    }

    .articlePage, .WYSIWYG, #articlePage, [class*="article-body"], [data-test="article-body"] {
        background-color: var(--bg-primary) !important;
        color: var(--text-primary) !important;
        line-height: 1.75;
    }

    .WYSIWYG p, [data-test="article-body"] p {
        color: #d1d5db !important;
    }

    .WYSIWYG blockquote, blockquote {
        background-color: var(--bg-secondary) !important;
        border-left: 4px solid var(--accent-blue) !important;
        color: var(--text-secondary) !important;
    }

    [class*="ticker"], .instrumentLink, a[href*="/equities/"], a[href*="/indices/"], a[href*="/currencies/"] {
        color: var(--accent-blue) !important;
    }

    .outerEleWrapper {
        background: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
    }

    /* ==========================================================================
       6. SCROLLBARS
       ========================================================================== */
    ::-webkit-scrollbar {
        width: 10px;
        height: 10px;
    }
    ::-webkit-scrollbar-track {
        background: var(--bg-primary);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--border-color);
        border-radius: 5px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: var(--text-muted);
    }
}
